def select_solver():
    from config import get_solver_config
    sc = get_solver_config(config)
    if not sc.get("enabled", True):
        log.info(f"Solver Engine {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Disabled (running without captcha solver)")
        return None, None

    provider = sc.get("provider", "bitsolver")
    api_key = sc.get("api_key", "")
    log.info(f"Solver Engine {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Selected {Fore.CYAN}{provider}{Style.RESET_ALL}")
    return provider, api_key

async def remove_invite_from_file(invite_code: str):
    async with file_lock:
        invites_file = Path("input/invites.txt")
        if not invites_file.exists():
            return
        try:
            lines = invites_file.read_text(encoding="utf-8").splitlines()
            new_lines = []
            removed = False
            for line in lines:
                parsed = parse_invite(line)
                if parsed == invite_code and not removed:
                    removed = True
                    continue
                new_lines.append(line)
            write_text_atomic(invites_file, "\n".join(new_lines) + ("\n" if new_lines else ""))
        except Exception as e:
            log.error(f"Failed to remove invite {invite_code} from file: {e}")

async def remove_token_from_file(token_str: str):
    async with file_lock:
        tokens_file = Path("input/tokens.txt")
        if not tokens_file.exists():
            return
        try:
            lines = tokens_file.read_text(encoding="utf-8").splitlines()
            new_lines = []
            removed = False
            for line in lines:
                token_val = line.split(":")[-1].strip() if ":" in line else line.strip()
                if token_val == token_str and not removed:
                    removed = True
                    continue
                new_lines.append(line)
            write_text_atomic(tokens_file, "\n".join(new_lines) + ("\n" if new_lines else ""))
            log.info(f"Removed token {token_str[:4]}...{token_str[-4:]} from input/tokens.txt")
        except Exception as e:
            log.error(f"Failed to remove token from input/tokens.txt: {e}")


async def requeue_or_drop_invite(invites, attempts, worker, invite, status, max_attempts,
                                 lock=None):
    """Put a failed invite back at the end of the queue while it has attempts left.

    A "Captcha Timeout" or an unrecognised join status used to append the invite
    again with no counter, so an invite that could never succeed cycled through
    the workers for the whole run and the queue never drained.

    The caller has already taken the invite off the queue. With one dispatcher
    per thread the queue is shared, so an invite is claimed and removed in a
    single locked step at the start of a turn; peeking at invites[0] here would
    no longer find it, and the invite would be lost rather than retried.
    """
    attempts[invite] = attempts.get(invite, 0) + 1
    if attempts[invite] >= max_attempts:
        log.warning(
            f"T{worker.id} Invite {Fore.YELLOW}{invite}{Style.RESET_ALL} failed "
            f"{attempts[invite]}x (last status={status}). Dropping it."
        )
        try:
            push_token_core_log(
                f"T{worker.id}: Invite {invite} failed {attempts[invite]}x - dropped", "error"
            )
        except Exception:
            pass
        try:
            os.makedirs("output", exist_ok=True)
            with open("output/failed_invites.txt", "a", encoding="utf-8") as f:
                f.write(f"{invite}\n")
        except Exception as e:
            log.warning(f"Could not record failed invite {invite}: {e}")
        await remove_invite_from_file(invite)
        return
    if lock is not None:
        async with lock:
            invites.append(invite)
    else:
        invites.append(invite)
    # The proxy is deliberately NOT rotated here. It is pinned to the token, and
    # the reported timezone follows the proxy IP, so swapping it on a failure
    # would move the account's country and clock mid-run -- the exact new-device
    # signal the pinning exists to remove. A failed turn only clears the cached
    # handle so the pin is re-resolved (picking up an edited proxies.txt).
    # ponytail: with a small proxy list a genuinely dead proxy stalls the tokens
    # pinned to it until proxies.txt is fixed; add a per-token failure counter
    # with a fallback to the rotation if that becomes the common case.
    worker.proxy = None
    worker.proxy_token = None


async def move_token_to_captchaed(token_str: str):
    """Record a captcha-retired token in output/captchaed.txt and remove it from
    the active pool. It is filed, not deleted, so the operator can see which
    tokens kept getting challenged, and it is never rotated back into use.
    """
    await move_token_to_file(token_str, "output/captchaed.txt")


async def move_token_to_quarantined(token_str: str):
    """File an account Discord has quarantined (403/10008 on a live invite, or
    the QUARANTINED/SPAMMER user flag) in output/quarantined.txt and drop it
    from the pool. Every join it attempts is refused after the captcha is
    solved, so keeping it active only burns solver credits.
    """
    await move_token_to_file(token_str, "output/quarantined.txt")


async def move_token_to_file(token_str: str, dest: str):
    async with file_lock:
        try:
            os.makedirs("output", exist_ok=True)
            # Write the full line from tokens.txt (email:pass:token or bare token)
            # so the record matches the input format, then drop it from tokens.txt.
            tokens_file = Path("input/tokens.txt")
            matched = token_str
            kept, removed = [], False
            if tokens_file.exists():
                lines = tokens_file.read_text(encoding="utf-8").splitlines()
                for line in lines:
                    val = line.split(":")[-1].strip() if ":" in line else line.strip()
                    if val == token_str and not removed:
                        matched = line
                        removed = True
                        continue
                    kept.append(line)
            # File it BEFORE rewriting tokens.txt: if the rewrite fails (disk
            # full, or on Windows a PermissionError while the dashboard has the
            # file open for read) the token must still be on record as
            # captcha'd, or it comes back into the active pool on restart.
            with open(dest, "a", encoding="utf-8") as f:
                f.write(f"{matched}\n")
            if removed:
                write_text_atomic(tokens_file, "\n".join(kept) + ("\n" if kept else ""))
            log.info(f"Token {token_str[:4]}...{token_str[-4:]} moved to {dest}")
        except Exception as e:
            log.error(f"Failed to move token to {dest}: {e}")


async def move_token_to_end_of_file(token_str: str):
    async with file_lock:
        tokens_file = Path("input/tokens.txt")
        if not tokens_file.exists():
            return
        try:
            lines = tokens_file.read_text(encoding="utf-8").splitlines()
            matched_line = None
            remaining_lines = []
            for line in lines:
                token_val = line.split(":")[-1].strip() if ":" in line else line.strip()
                if token_val == token_str and matched_line is None:
                    matched_line = line
                    continue
                remaining_lines.append(line)
            if matched_line:
                remaining_lines.append(matched_line)
                write_text_atomic(tokens_file, "\n".join(remaining_lines) + ("\n" if remaining_lines else ""))
                log.info(f"Moved token {token_str[:4]}...{token_str[-4:]} to bottom of input/tokens.txt")
        except Exception as e:
            log.error(f"Failed to move token to end of input/tokens.txt: {e}")

async def main():
    global SOLVER_TYPE, SOLVER_API_KEY, gen_count

    # Start the dashboard before authentication/input processing so operators
    # can submit tokens and invites through the web UI.
    dashboard_port = config.get("dashboard_port", 5050)
    try:
        start_dashboard(dashboard_port)
    except Exception as e:
        log.warning(f"Could not start dashboard: {e}")

    shutdown_requested = False
    scheduler_task = None

    def handle_shutdown(sig, frame):
        nonlocal shutdown_requested
        if shutdown_requested:
            log.warning("Force exiting immediately...")
            os._exit(1)
        log.warning("Ctrl+C / termination signal received! Initiating graceful shutdown...")
        log.info("Finishing active tasks, no new tasks will be scheduled. Press Ctrl+C again to force exit.")
        shutdown_requested = True
        
        # Cancel the scheduler task to interrupt any blocking await (like pause delays)
        if scheduler_task and not scheduler_task.done():
            scheduler_task.cancel()

    signal.signal(signal.SIGINT, handle_shutdown)
    signal.signal(signal.SIGTERM, handle_shutdown)

    # Start Discord bot (no-op if bot_token not set)
    try:
        start_bot()
    except Exception as e:
        log.warning(f"Could not start Discord bot: {e}")

    proxy_manager = ProxyManager()

    # Solver selection
    SOLVER_TYPE, SOLVER_API_KEY = None, None

    # Pre-seed output file caches into memory to prevent disk lock contention
    try:
        from utils.account import seed_output_file_caches
        seed_output_file_caches()
    except Exception:
        pass

    # Wait for dashboard input instead of prompting in the terminal or exiting.
    invites_file = Path("input/invites.txt")
    tokens_file = Path("input/tokens.txt")
    invites = []
    tokens = []
    last_input_notice = 0.0
    while not invites or not tokens:
        invites = [
            parse_invite(line)
            for line in invites_file.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ] if invites_file.exists() else []
        tokens = [
            line.strip()
            for line in tokens_file.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ] if tokens_file.exists() else []

        if not invites:
            fallback_invite = config.get("invite", {}).get("invite", "")
            if fallback_invite:
                invites = [parse_invite(fallback_invite)]
        if invites and tokens:
            break
        if time.time() - last_input_notice >= 10:
            log.info("Waiting for tokens and invites from the dashboard at http://127.0.0.1:%s", dashboard_port)
            last_input_notice = time.time()
        await asyncio.sleep(1)

    # Parse and extract actual token strings
    raw_lines = tokens
    tokens = []
    for line in raw_lines:
        if ":" in line:
            parts = line.split(":")
            tokens.append(parts[-1].strip())
        else:
            tokens.append(line)
    # One worker per account: a token listed twice (bare and as email:pass:token)
    # hashes to the same thread and would get two workers, doubling its join
    # rate past the per-token gap. Order is kept so thread assignment is stable.
    before = len(tokens)
    tokens = list(dict.fromkeys(tokens))
    if len(tokens) != before:
        log.warning(f"Dropped {before - len(tokens)} duplicate token line(s) from input/tokens.txt")

    # Dynamic scheduling setup
    max_guild_limit = int(config.get("max_guild_limit", 80) or 80)
    guilds_db = load_guilds_db()
    
    invites_to_process = list(invites)
    active_tokens = list(tokens)
    STATS["total_tokens"] = len(tokens)
    STATS["active_tokens"] = len(active_tokens)
    STATS["tokens_in_use"] = 0
    STATS["total_invites"] = len(invites)
    STATS["max_guild_limit"] = max_guild_limit
    token_last_use_time = {}
    current_token_index = 0
    token_proxies = {}
    
    token_lock = asyncio.Lock()
    invite_lock = asyncio.Lock()

    # Batch pause variables (pause for 5 minutes after 3-6 joins)
    tokens_in_use = set()
    invites_in_use = set()

    NUM_THREADS = int(config.get("threads", 2))
    solver_name = SOLVER_TYPE if SOLVER_TYPE else "disabled"
    log.info(
        f"Engine Ready {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} "
        f"Threads: {Fore.CYAN}{NUM_THREADS}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
        f"Tokens: {Fore.CYAN}{len(tokens)}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
        f"Invites: {Fore.YELLOW}{len(invites)}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
        "Challenge handling: disabled"
    )

    threading.Thread(target=title_loop, daemon=True).start()

    # Tracking which tokens are fully exhausted or flagged
    exhausted_tokens = set()

    async def worker_loop(thread_id: int):
        nonlocal current_token_index
        global gen_count
        min_batch = int(config.get("min_batch_joins", 30))
        max_batch = int(config.get("max_batch_joins", 40))
        if min_batch > max_batch:
            min_batch, max_batch = max_batch, min_batch
        joins_in_batch = 0
        batch_target = random.randint(min_batch, max_batch)

        while True:
            if shutdown_requested:
                break

            invite = None
            async with invite_lock:
                if not invites_to_process:
                    break
                for inv in list(invites_to_process):
                    if inv not in invites_in_use:
                        invite = inv
                        invites_in_use.add(inv)
                        invites_to_process.remove(inv)
                        break

            if not invite:
                await asyncio.sleep(1.0)
                async with invite_lock:
                    if not invites_to_process and not invites_in_use:
                        break
                continue

            token = None
            while True:
                if shutdown_requested:
                    break
                async with token_lock:
                    current_time = time.time()
                    join_method = config.get("join_method", "normal")
                    
                    if join_method == "cycle" and active_tokens:
                        if current_token_index >= len(active_tokens):
                            current_token_index = 0
                        
                        found_token = None
                        for i in range(len(active_tokens)):
                            idx = (current_token_index + i) % len(active_tokens)
                            t = active_tokens[idx]
                            if t in exhausted_tokens:
                                continue
                            if t in tokens_in_use:
                                continue
                            if current_time - token_last_use_time.get(t, 0) < 300.0:
                                continue
                            joins = len(guilds_db.get(t, []))
                            if joins < max_guild_limit:
                                found_token = t
                                current_token_index = (idx + 1) % len(active_tokens)
                                break
                        
                        if found_token:
                            token = found_token
                            tokens_in_use.add(token)
                            STATS["tokens_in_use"] = len(tokens_in_use)
                            if token not in guilds_db:
                                guilds_db[token] = []
                            guilds_db[token].append("placeholder_guild_id")
                    else:
                        for t in active_tokens:
                            if t in exhausted_tokens or t in tokens_in_use:
                                continue
                            joins = len(guilds_db.get(t, []))
                            if joins >= max_guild_limit:
                                exhausted_tokens.add(t)
                                continue
                            token = t
                            tokens_in_use.add(t)
                            STATS["tokens_in_use"] = len(tokens_in_use)
                            if t not in guilds_db:
                                guilds_db[t] = []
                            guilds_db[t].append("placeholder_guild_id")
                            break
                if token:
                    break

                async with token_lock:
                    any_slots_left = any(len(guilds_db.get(t, [])) < max_guild_limit for t in active_tokens if t not in exhausted_tokens)
                    if not any_slots_left:
                        break

                await asyncio.sleep(0.5)

            if not token:
                async with invite_lock:
                    invites_to_process.append(invite)
                    invites_in_use.discard(invite)
                break

            try:
                async with token_lock:
                    if token not in token_proxies:
                        # Pinned to the token, not drawn from the rotation: the
                        # reported timezone follows the proxy IP, so a rotating
                        # proxy moved the account's country and clock between runs.
                        token_proxies[token] = await asyncio.to_thread(
                            proxy_manager.get_proxy_for_token, token
                        )
                    proxy = token_proxies[token]
                # Coerced: a JSON string here raised TypeError deep in join_server,
                # which surfaced as "failed" and drained the whole invite list.
                max_guild_limit_val = int(config.get("max_guild_limit", 80) or 80)
                min_member_count = int(config.get("min_member_count", 0) or 0)

                current_num = thread_id

                try:
                    status = await asyncio.to_thread(
                        join_server,
                        token,
                        invite,
                        proxy,
                        current_num,
                        SOLVER_TYPE,
                        SOLVER_API_KEY,
                        3, # max_retries
                        max_guild_limit_val,
                        min_member_count,
                    )
                except asyncio.CancelledError:
                    raise
                except Exception as e:
                    # join_server reaches out to the network, the solver service and
                    # the browser. An escape here used to kill this worker for the
                    # rest of the run; asyncio.gather swallows the exception, so the
                    # pool silently shrank with no error on screen.
                    log.error(f"join_server crashed for invite={invite}: {e}", exc_info=True)
                    status = "failed"
                
                if status in ("Joined", "Joined_Captcha_Exhausted"):
                    await remove_invite_from_file(invite)
                    joins_in_batch += 1

                    # Check if THIS thread has completed its individual batch limit
                    if joins_in_batch >= batch_target:
                        min_batch_pause = int(config.get("min_batch_delay", 300))
                        max_batch_pause = int(config.get("max_batch_delay", 480))
                        if min_batch_pause > max_batch_pause:
                            min_batch_pause, max_batch_pause = max_batch_pause, min_batch_pause
                        delay_secs = random.randint(min_batch_pause, max_batch_pause)
                        log.info(
                            f"Batch complete ({joins_in_batch} joins) {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} "
                            f"Pausing thread for {delay_secs / 60:.1f}m (other threads continue)..."
                        )
                        await asyncio.sleep(delay_secs)
                        joins_in_batch = 0
                        batch_target = random.randint(min_batch, max_batch)
                        log.info(f"Cooldown finished {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Resuming joins.")

                elif status == "Already Member":
                    await remove_invite_from_file(invite)
                    async with token_lock:
                        if token in guilds_db and guilds_db[token]:
                            guilds_db[token].pop()
                elif status in ("invalid_invite", "min_members_limit"):
                    await remove_invite_from_file(invite)

                if status in ("invalid", "locked", "Joined_Captcha_Exhausted", "limited"):
                    await remove_token_from_file(token)
                    async with token_lock:
                        exhausted_tokens.add(token)
                        if token in active_tokens:
                            active_tokens.remove(token)
                            STATS["active_tokens"] = len(active_tokens)
                            token_proxies.pop(token, None)
                            log.warning(f"Token pool updated {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} token={Fore.CYAN}{token[:4]}...{token[-4:]}{Style.RESET_ALL} status={Fore.LIGHTYELLOW_EX}{status}{Style.RESET_ALL} (quarantined/removed)")

                # If join failed or skipped, free placeholder slot and re-queue invite if needed
                if status in ("invalid", "locked", "limited", "captcha_skip", "min_members_limit", "failed", "action_blocked"):
                    async with token_lock:
                        if token in guilds_db and guilds_db[token]:
                            guilds_db[token].pop()
                        # If action_blocked, rotate this token to the back of active_tokens and file so next restart preserves order
                        if status == "action_blocked":
                            await move_token_to_end_of_file(token)
                            if token in active_tokens and len(active_tokens) > 1:
                                active_tokens.remove(token)
                                active_tokens.append(token)
                                log.info(f"Token rotated {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} token={Fore.CYAN}{token[:4]}...{token[-4:]}{Style.RESET_ALL} status=action_blocked (moved to end)")
                    if status in ("invalid", "locked", "limited", "captcha_skip", "action_blocked"):
                        async with invite_lock:
                            invites_to_process.append(invite)

            finally:
                if token:
                    async with token_lock:
                        tokens_in_use.discard(token)
                        STATS["tokens_in_use"] = len(tokens_in_use)
                        token_last_use_time[token] = time.time()
                async with invite_lock:
                    invites_in_use.discard(invite)

    class TokenCoreWorker:
        def __init__(self, worker_id: int, token: str, limit: int):
            self.id = worker_id
            self.token = token
            self.joins = 0
            self.limit = limit
            self.status = "Idle"
            self.current_invite = "—"
            self.proxy = None
            self.proxy_token = None
            self.retired = False
            self.thread_id = 0
            # Earliest time this token may join again. A per-token cooldown so the
            # gap between a token's own joins stays constant no matter how many
            # workers share the thread -- fewer tokens must NOT mean faster joins.
            self.next_join_ok = 0.0

    async def run_token_core_engine():
        nonlocal shutdown_requested
        # A "thread" is one exit IP with a group of workers behind it. `threads`
        # says how many proxies to spread across (bounded by how many are
        # loaded), and `workers_per_thread` says how many workers sit on each.
        # Total concurrency is the product, so raising either raises throughput,
        # but only `threads` adds IPs to spread it over.
        workers_per_thread = max(1, int(config.get("workers_per_thread", 9)))
        proxy_pool = proxy_manager.active_pool()
        requested_threads = max(1, int(NUM_THREADS))
        thread_count = min(requested_threads, len(proxy_pool)) if proxy_pool else 1
        if proxy_pool and requested_threads > len(proxy_pool):
            log.warning(
                f"threads={requested_threads} but only {len(proxy_pool)} "
                f"{'proxy is' if len(proxy_pool) == 1 else 'proxies are'} loaded; "
                f"running {thread_count} thread(s). Add more lines to "
                f"input/proxies.txt to spread the load over more IPs."
            )

        engine_workers_count = min(thread_count * workers_per_thread, len(tokens))
        if engine_workers_count <= 0:
            log.warning("No tokens available to initialize the Fleet engine.")
            return

        token_join_limit = int(config.get("token_join_limit", 33))
        min_disp_delay = float(config.get("min_dispatcher_delay", 35))
        max_disp_delay = float(config.get("max_dispatcher_delay", 45))
        if min_disp_delay > max_disp_delay:
            min_disp_delay, max_disp_delay = max_disp_delay, min_disp_delay

        # Per-token join gap: the minimum time between one token's own joins,
        # enforced independently of how many workers are running. Defaults to the
        # gap a full thread produces (workers_per_thread x dispatcher delay), so a
        # thread at full strength is unchanged, but a thread with few tokens does
        # NOT let them join any faster. Set min/max_token_join_gap to override.
        _full_gap_lo = workers_per_thread * min_disp_delay
        _full_gap_hi = workers_per_thread * max_disp_delay
        min_token_gap = float(config.get("min_token_join_gap", _full_gap_lo))
        max_token_gap = float(config.get("max_token_join_gap", _full_gap_hi))
        if min_token_gap > max_token_gap:
            min_token_gap, max_token_gap = max_token_gap, min_token_gap

        min_member_count = int(config.get("min_member_count", 0) or 0)
        max_guild_limit = int(config.get("max_guild_limit", 80) or 80)

        admin_id = 0
        if config.get("admin_user_ids"):
            try:
                admin_id = int(config.get("admin_user_ids")[0])
            except Exception:
                admin_id = 0

        # Group tokens by the thread they are pinned to, so a token never moves
        # between exit IPs. Each thread then fills its own worker slots from its
        # own group and keeps the rest as that thread's standby pool.
        by_thread = {t: [] for t in range(thread_count)}
        for tok in tokens:
            by_thread[proxy_manager.thread_index_for_token(tok, thread_count)].append(tok)

        workers = []
        by_worker_thread = {}
        standby_by_thread = {}
        for t in range(thread_count):
            group = by_thread[t]
            slots = min(workers_per_thread, len(group))
            by_worker_thread[t] = []
            for k in range(slots):
                w = TokenCoreWorker(len(workers) + 1, group[k], token_join_limit)
                w.thread_id = t
                w.proxy = proxy_pool[t] if proxy_pool else None
                w.proxy_token = group[k]
                workers.append(w)
                by_worker_thread[t].append(w)
            standby_by_thread[t] = group[slots:]

        engine_workers_count = len(workers)
        # Fleet-wide view, for the startup banner only; each thread works its own
        # standby list so a replacement token never crosses to another exit IP.
        standby_tokens = [tok for t in range(thread_count) for tok in standby_by_thread[t]]
        total_tokens_count = len(tokens)
        tokens_retired_count = 0

        init_token_core_workers(num_workers=engine_workers_count, limit=token_join_limit)
        for w in workers:
            set_worker_state(w.id, token=w.token, invite="—", joins=0, limit=token_join_limit, status="Idle")

        update_token_core_telemetry(
            session_created=STATS.get("unlocked", 0),
            captcha_fails=STATS.get("captcha_fails", 0),
            invalid_tokens=STATS.get("invalid", 0) + STATS.get("locked", 0),
            tokens_left=len(standby_tokens),
            invites_left=len(invites_to_process),
            session_stopped=False,
            user_id=admin_id,
            total_tokens=total_tokens_count,
            tokens_retired=tokens_retired_count,
        )

        log.info(
            f"Fleet Dispatcher Ready {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} "
            f"{Fore.CYAN}{thread_count}{Style.RESET_ALL} thread(s) x "
            f"{Fore.CYAN}{workers_per_thread}{Style.RESET_ALL} workers = "
            f"{Fore.CYAN}{len(workers)}{Style.RESET_ALL} active {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
            f"Limit/Token: {Fore.YELLOW}{token_join_limit}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
            f"Standby Tokens: {Fore.CYAN}{len(standby_tokens)}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
            f"Pacing: {Fore.GREEN}{min_disp_delay:.0f}-{max_disp_delay:.0f}s (~{(len(workers) * min_disp_delay)/60:.1f}m/token){Style.RESET_ALL}"
        )

        invite_attempts = {}
        MAX_INVITE_ATTEMPTS = int(config.get("max_invite_attempts", 5))

        # One dispatcher per thread. A thread owns exactly one proxy and the
        # workers under it, and paces itself, so an added proxy adds throughput
        # instead of thinning a fixed global rate across more workers. The
        # invite queue is the one thing shared between them, and it is claimed
        # under invite_lock so two threads never take the same invite.
        async def run_thread(thread_id, workers, standby_by_thread):
            nonlocal tokens_retired_count
            standby_tokens = standby_by_thread[thread_id]
            current_idx = 0
            while not shutdown_requested and invites_to_process:
                active_workers = [w for w in workers if not w.retired]
                if not active_workers:
                    log.warning("All Fleet workers have retired and standby token pool is exhausted.")
                    break

                # Per-token cooldown: only consider workers whose token is off
                # cooldown. If every active worker is still cooling down, wait for
                # the earliest instead of spinning -- this is what keeps the gap
                # per token constant when there are fewer workers than the thread
                # could hold.
                now = time.time()
                ready = [w for w in active_workers if w.next_join_ok <= now]
                if not ready:
                    wake = min(w.next_join_ok for w in active_workers)
                    nap = max(1.0, min(wake - now, 300.0))
                    try:
                        await asyncio.sleep(nap)
                    except asyncio.CancelledError:
                        break
                    continue

                worker = workers[current_idx % len(workers)]
                current_idx += 1

                if worker.retired or worker.next_join_ok > time.time():
                    continue

                # The exit IP belongs to the thread, and a token only ever sits in
                # one thread, so this never moves an account between IPs. It only
                # re-resolves after a failed turn cleared the cached handle, which
                # also picks up an edited proxies.txt.
                if not worker.proxy or worker.proxy_token != worker.token:
                    fresh = proxy_manager.active_pool()
                    worker.proxy = (fresh[worker.thread_id]
                                    if worker.thread_id < len(fresh)
                                    else (proxy_pool[worker.thread_id] if proxy_pool else None))
                    worker.proxy_token = worker.token

                # Loop through invites for THIS worker until an actual join attempt is made.
                # If an invite was already joined globally or is invalid, remove it immediately
                # and take the next invite so this worker never skips its join turn!
                turn_completed = False
                while not shutdown_requested and invites_to_process and not turn_completed:
                    # Claim the invite under the lock and take it off the queue in
                    # the same step. Peeking here and popping later let two
                    # threads work the same invite, which breaks the rule that a
                    # server is joined by exactly one token.
                    async with invite_lock:
                        if not invites_to_process:
                            break
                        invite = invites_to_process.pop(0)
                    worker.current_invite = invite
                    worker.status = "Joining"
                    set_worker_state(worker.id, invite=invite, status="Joining")
                    update_token_core_telemetry(tokens_left=len(standby_tokens), invites_left=len(invites_to_process))

                    log.info(
                        f"T{worker.id} Dispatching {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} "
                        f"token={Fore.CYAN}{worker.token[:4]}...{worker.token[-4:]}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
                        f"target={Fore.YELLOW}discord.gg/{invite}{Style.RESET_ALL} {Fore.LIGHTBLACK_EX}│{Style.RESET_ALL} "
                        f"joins={Fore.GREEN}{worker.joins}/{worker.limit}{Style.RESET_ALL}"
                    )

                    try:
                        status = await asyncio.to_thread(
                            join_server,
                            worker.token,
                            invite,
                            worker.proxy,
                            worker.id,
                            SOLVER_TYPE,
                            SOLVER_API_KEY,
                            3,
                            max_guild_limit,
                            min_member_count,
                        )
                    except asyncio.CancelledError:
                        raise
                    except Exception as e:
                        # The fleet engine runs the whole fleet from a single dispatcher task,
                        # so an exception escaping here does not lose one worker, it ends
                        # the entire run. Demote it to a failed turn instead.
                        log.error(
                            f"T{worker.id} join_server crashed for invite={invite}: {e}",
                            exc_info=True,
                        )
                        push_token_core_log(f"T{worker.id}: join crashed ({type(e).__name__}) - invite requeued", "error")
                        status = "failed"

                    if status == "Already Member":
                        # Server already joined globally: remove invite across all tokens and immediately take next invite for this worker!
                        push_token_core_log(f"T{worker.id}: Server already joined globally (discord.gg/{invite}) - taking next invite", "info")
                        log.info(f"T{worker.id} Server Already Joined {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} discord.gg/{invite} already joined by a token. Removing invite and trying next server for T{worker.id}...")
                        await remove_invite_from_file(invite)
                        update_token_core_telemetry(invites_left=len(invites_to_process))
                        continue

                    elif status in ("invalid_invite", "min_members_limit"):
                        # Invalid invite: remove and immediately take next invite for this worker!
                        push_token_core_log(f"T{worker.id}: Invite {status} (discord.gg/{invite}) - taking next invite", "error")
                        log.info(f"T{worker.id} Invite {status} {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Removing discord.gg/{invite} and trying next server for T{worker.id}...")
                        await remove_invite_from_file(invite)
                        update_token_core_telemetry(invites_left=len(invites_to_process))
                        continue

                    elif status in ("Joined", "Joined_Captcha_Exhausted"):
                        worker.joins += 1
                        worker.status = "Joined"
                        # Hold this token off until its per-token gap has passed,
                        # so its own join rate is the same whether it shares the
                        # thread with nine other tokens or runs alone.
                        worker.next_join_ok = time.time() + random.uniform(min_token_gap, max_token_gap)
                        set_worker_state(worker.id, joins=worker.joins, status="Joined")
                        await remove_invite_from_file(invite)
                        push_token_core_log(f"T{worker.id}: Joined discord.gg/{invite} joins={worker.joins}", "success")
                        log.info(f"T{worker.id} Join Success {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} joins={worker.joins}/{worker.limit}")

                        # Quota check & automatic retirement
                        if worker.joins >= worker.limit:
                            tokens_retired_count += 1
                            log.info(f"T{worker.id} Quota Reached {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Token reached join limit ({worker.joins}/{worker.limit}). Retiring token.")
                            push_token_core_log(f"T{worker.id}: Token reached limit ({worker.limit} joins) - retired", "info")
                            # standby_tokens IS this thread's group, so popping
                            # from it is the whole removal.
                            if standby_tokens:
                                new_tok = standby_tokens.pop(0)
                                worker.token = new_tok
                                worker.joins = 0
                                # Same thread, so the same exit IP: a replacement
                                # token is drawn from this thread's own group.
                                worker.proxy = proxy_pool[worker.thread_id] if proxy_pool else None
                                worker.proxy_token = new_tok
                                worker.status = "Standby Active"
                                set_worker_state(worker.id, token=worker.token, joins=0, status="Standby Active")
                                push_token_core_log(f"T{worker.id}: Assigned fresh standby token {worker.token[:4]}...", "info")
                                log.info(f"T{worker.id} Token Rotated {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Standby token assigned ({len(standby_tokens)} left in pool)")
                            else:
                                worker.retired = True
                                worker.status = "Retired"
                                set_worker_state(worker.id, status="Retired")
                        turn_completed = True

                    elif status == "Captcha Timeout":
                        worker.status = "Captcha Timeout"
                        set_worker_state(worker.id, status="Captcha Timeout")
                        push_token_core_log(f"T{worker.id}: Captcha timeout invite={invite}", "captcha")
                        await requeue_or_drop_invite(invites_to_process, invite_attempts, worker,
                                                     invite, status, MAX_INVITE_ATTEMPTS,
                                                     lock=invite_lock)
                        turn_completed = True

                    elif status == "captcha_skip":
                        # A captcha this token could not pass (solver off, or the
                        # solve failed). Drop the invite so no other token burns a
                        # turn on a captcha-gated server, then move this token on.
                        # Set remove_captcha_invites=false to re-queue instead.
                        worker.status = "Captcha"
                        set_worker_state(worker.id, status="Captcha")
                        if config.get("remove_captcha_invites", True):
                            push_token_core_log(f"T{worker.id}: Captcha on invite - dropping invite", "captcha")
                            if invite in invite_attempts:
                                invite_attempts.pop(invite, None)
                            await remove_invite_from_file(invite)
                        else:
                            await requeue_or_drop_invite(invites_to_process, invite_attempts, worker,
                                                         invite, status, MAX_INVITE_ATTEMPTS,
                                                         lock=invite_lock)
                        turn_completed = True

                    elif status == "captcha_retired":
                        # This token was challenged past max_captcha_before_skip.
                        # It is filed to output/captchaed.txt and NOT rotated or
                        # reused. The worker slot then fills from the standby pool
                        # so the fleet keeps running with a fresh token; the bad
                        # token is the one thing that never comes back. The invite
                        # is dropped too (it was captcha-gated for this token).
                        tokens_retired_count += 1
                        worker.status = "Captcha Retired"
                        set_worker_state(worker.id, status="Captcha Retired")
                        push_token_core_log(f"T{worker.id}: Token captcha'd out - moved to captchaed.txt", "captcha")
                        if config.get("remove_captcha_invites", True):
                            await remove_invite_from_file(invite)
                        else:
                            await requeue_or_drop_invite(invites_to_process, invite_attempts, worker,
                                                         invite, status, MAX_INVITE_ATTEMPTS, lock=invite_lock)
                        await move_token_to_captchaed(worker.token)
                        if standby_tokens:
                            new_tok = standby_tokens.pop(0)
                            worker.token = new_tok
                            worker.joins = 0
                            worker.proxy = proxy_pool[worker.thread_id] if proxy_pool else None
                            worker.proxy_token = new_tok
                            worker.status = "Standby Active"
                            set_worker_state(worker.id, token=worker.token, joins=0, status="Standby Active")
                        else:
                            worker.retired = True
                            worker.status = "Retired"
                            set_worker_state(worker.id, status="Retired")
                        turn_completed = True

                    elif status in ("invalid", "locked", "limited", "quarantined", "action_blocked"):
                        tokens_retired_count += 1
                        worker.status = status
                        set_worker_state(worker.id, status=status)
                        push_token_core_log(f"T{worker.id}: Token {status} - rotating from pool", "error")
                        # The invite is fine; the token is what is unusable. Put
                        # it back for another token, with no attempt counted --
                        # it used to be lost for the rest of the run here.
                        async with invite_lock:
                            invites_to_process.append(invite)
                        if status in ("quarantined", "action_blocked"):
                            # Discord refuses every join from this account, and
                            # only after the captcha has been solved (403/10008).
                            # In fleet mode this used to fall through to the
                            # generic branch: the invite ate a failure and the
                            # token stayed active, solving captchas it could
                            # never use. File it so it never comes back.
                            await move_token_to_quarantined(worker.token)
                        else:
                            await remove_token_from_file(worker.token)
                        if standby_tokens:
                            new_tok = standby_tokens.pop(0)
                            worker.token = new_tok
                            worker.joins = 0
                            worker.proxy = proxy_pool[worker.thread_id] if proxy_pool else None
                            worker.proxy_token = new_tok
                            worker.status = "Standby Active"
                            set_worker_state(worker.id, token=worker.token, joins=0, status="Standby Active")
                        else:
                            worker.retired = True
                            worker.status = "Retired"
                            set_worker_state(worker.id, status="Retired")
                        turn_completed = True

                    else:
                        worker.status = status
                        set_worker_state(worker.id, status=status)
                        await requeue_or_drop_invite(invites_to_process, invite_attempts, worker,
                                                     invite, status, MAX_INVITE_ATTEMPTS,
                                                     lock=invite_lock)
                        turn_completed = True

                update_token_core_telemetry(
                    session_created=STATS.get("unlocked", 0),
                    captcha_fails=STATS.get("captcha_fails", 0),
                    invalid_tokens=STATS.get("invalid", 0) + STATS.get("locked", 0),
                    tokens_left=len(standby_tokens),
                    invites_left=len(invites_to_process),
                    total_tokens=total_tokens_count,
                    tokens_retired=tokens_retired_count,
                )

                # Global sequential round-robin queue stagger delay (35 to 45 seconds)
                if not shutdown_requested and invites_to_process:
                    # Inside a burst the captured account left 60-96s between joins.
                    stagger = random.uniform(min_disp_delay, max_disp_delay)
                    # The per-token gap is enforced directly by next_join_ok, so
                    # report that rather than workers x stagger -- the old figure
                    # shrank as workers retired and understated the real cooldown.
                    approx_cycle = ((min_token_gap + max_token_gap) / 2.0) / 60.0
                    log.info(
                        f"Queue Pacing {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} "
                        f"Next worker in {Fore.CYAN}{stagger:.1f}s{Style.RESET_ALL} "
                        f"{Fore.LIGHTBLACK_EX}(individual token rest cooldown ~{approx_cycle:.1f}m){Style.RESET_ALL}"
                    )
                    try:
                        await asyncio.sleep(stagger)
                    except asyncio.CancelledError:
                        break

        thread_tasks = [
            asyncio.create_task(run_thread(t, by_worker_thread[t], standby_by_thread))
            for t in sorted(by_worker_thread)
            if by_worker_thread[t]
        ]
        if not thread_tasks:
            log.warning('No Fleet threads could be started.')
            return
        log.info(
            f"Fleet Threads {Fore.LIGHTBLACK_EX}\u203a{Style.RESET_ALL} running {Fore.CYAN}{len(thread_tasks)}{Style.RESET_ALL} independent dispatcher(s), one per exit IP"
        )
        await asyncio.gather(*thread_tasks, return_exceptions=True)

    # "fleet" is the multi-thread engine (one exit IP per thread, N workers each).
    # "token_core" is accepted as a legacy alias so older configs keep working.
    engine_mode = str(config.get("join_engine_mode", "fleet")).lower().strip()
    if engine_mode in ("fleet", "token_core"):
        log.info(f"Engine Dispatcher {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Operating in {Fore.GREEN}Fleet Mode{Style.RESET_ALL}")
        scheduler_task = asyncio.create_task(run_token_core_engine())
        try:
            await scheduler_task
        except asyncio.CancelledError:
            log.info("Fleet dispatcher stopped by shutdown request.")
        finally:
            update_token_core_telemetry(session_stopped=True)
            log.info(f"Gateway cleanup {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Closing all active WebSocket connections...")
            await asyncio.to_thread(close_all_gateways)
    else:
        log.info(f"Engine Dispatcher {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Operating in {Fore.CYAN}Classic Concurrent Mode{Style.RESET_ALL}")
        # Launch independent per-thread worker tasks
        worker_tasks = [asyncio.create_task(worker_loop(i + 1)) for i in range(NUM_THREADS)]
        try:
            await asyncio.gather(*worker_tasks, return_exceptions=True)
        except asyncio.CancelledError:
            log.info("Threads stopped by shutdown request.")
        finally:
            log.info(f"Gateway cleanup {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} Closing all active WebSocket connections...")
            await asyncio.to_thread(close_all_gateways)

    log.info(f"Session finished {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} All server join tasks completed or tokens exhausted!")
    log.info(f"Discord Bot & Dashboard {Fore.LIGHTBLACK_EX}›{Style.RESET_ALL} 24/7 online. Use /addtokens or /addinvites, then /restart to resume.")

    # Keep the main process alive so the Discord bot and Web Dashboard stay active
    while True:
        await asyncio.sleep(3600)

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except (KeyboardInterrupt, SystemExit):
        pass
    except Exception:
        # A frozen exe launched by double-click closes its console the instant it
        # exits, so an unhandled error would vanish before it could be read. Print
        # the traceback and wait for a keypress so the operator can see what
        # broke instead of the window just disappearing.
        import traceback
        traceback.print_exc()
        try:
            input("\nAn unexpected error occurred (details above). Press Enter to exit...")
        except Exception:
            pass
        sys.exit(1)